 WHEN 'A-47' THEN '開発scenario選択' WHEN 'A-48' THEN '要件変更・traceability' WHEN 'A-49' THEN 'modeling scenario' WHEN 'A-50' THEN 'test戦略scenario' WHEN 'A-51' THEN '複合test case' WHEN 'A-52' THEN '変更事故scenario' WHEN 'A-53' THEN '日程短縮scenario' WHEN 'A-54' THEN 'EVM総合判断' WHEN 'A-55' THEN 'EVM総合判断' WHEN 'A-56' THEN 'risk scenario' WHEN 'A-57' THEN 'service level改善' WHEN 'A-58' THEN '運用障害scenario' WHEN 'A-59' THEN '監査scenario' WHEN 'A-60' THEN '不正防止scenario' WHEN 'A-61' THEN '戦略導出scenario' WHEN 'A-62' THEN '事業portfolio scenario' WHEN 'A-63' THEN '業界構造scenario' WHEN 'A-64' THEN 'marketing scenario' WHEN 'A-65' THEN '利益計画scenario' WHEN 'A-66' THEN '投資判断scenario' WHEN 'A-67' THEN 'software権利scenario' WHEN 'A-68' THEN 'data活用scenario' END,3 FROM ap_concepts WHERE sort_order BETWEEN 47 AND 68;

-- Seed one concept-specific question for every problem type.
INSERT OR REPLACE INTO ap_concept_questions(problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT t.id,1,
CASE c.concept_code||'-'||t.type_no
 WHEN 'A-47-1' THEN '요구변경이 매우 잦고 짧은 주기로 release하는 project에 일반적으로 더 적합한 접근은?' WHEN 'A-47-2' THEN 'Agile에서 우선순위가 정해진 요구목록을 무엇이라 하는가?' WHEN 'A-47-3' THEN '규제문서와 단계승인이 매우 엄격하고 요구가 안정적인 project라면 어떤 접근이 상대적으로 적합한가?'
